import{_ as p,r as n,o as l,c as o,e as s,a as c,s as i}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"Partial 字段 - October CMS - 3.x","titleTemplate":false,"description":"表单 UI","frontmatter":{"subtitle":"表单 UI","shortname":"Partial"},"headers":[{"level":2,"title":"访问变量","slug":"访问变量","link":"#访问变量","children":[]},{"level":2,"title":"使用视图模板","slug":"使用视图模板","link":"#使用视图模板","children":[{"level":4,"title":"另请参阅","slug":"另请参阅","link":"#另请参阅","children":[]}]}],"relativePath":"3.x/zh-cn/element/form/ui-partial.md","filePath":"3.x/zh-cn/element/form/ui-partial.md"}'),r={name:"3.x/zh-cn/element/form/ui-partial.md"};function d(u,a,k,h,m,g){const e=n("pre-heading"),t=n("post-heading");return l(),o("div",null,[s(e),a[0]||(a[0]=c("h1",null,"Partial 字段",-1)),s(t),a[1]||(a[1]=i(`<p><code>partial</code> UI 元素渲染一个部件，<code>path</code> 值可以引用部件视图文件，否则将使用字段名称作为部件名称。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">content</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Content
    <span class="token key atrule">type</span><span class="token punctuation">:</span> partial
    <span class="token key atrule">path</span><span class="token punctuation">:</span> field_content
</code></pre></div><p>支持以下<a href="./../form-fields.html">字段属性</a>。</p><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>描述</th></tr></thead><tbody><tr><td><strong>path</strong></td><td><a href="./../../extend/system/views.html">部件视图文件</a>或<a href="./../../extend/services/response-view.html">视图模板代码</a>的路径，默认为以 <strong>field_</strong> 为前缀的字段名称。</td></tr></tbody></table></div><p>当 <code>path</code> 设置为非限定文件名（不包含目录路径和扩展名的文件名）时，源路径将被确定为模型或控制器目录。以下示例将在 <strong>../models/mymodel/_field_for_content.php</strong> 或 <strong>../controllers/mycontroller/_field_for_content.php</strong> 中查找部件文件。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">content</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> partial
    <span class="token key atrule">path</span><span class="token punctuation">:</span> field_for_content
</code></pre></div><p>您可以指定完全限定的 <code>path</code> 来访问模型或控制器目录之外的部件。这对于在不同定义之间共享部件非常有用。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">content</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> partial
    <span class="token key atrule">path</span><span class="token punctuation">:</span> $/acme/blog/partials/_field_content.php
</code></pre></div><h2 id="访问变量"><a href="#访问变量" class="header-anchor">#</a> 访问变量</h2><p>部件渲染时，以下变量在部件内部可用。</p><ul><li><code>$value</code> 是当前字段值（如果存在）。</li><li><code>$model</code> 是字段使用的<a href="./../../extend/system/models.html">模型</a></li><li><code>$field</code> 是已配置的类对象 <code>Backend\\Classes\\FormField</code></li></ul><p>以下是 <strong>_field_content.php</strong> 文件的一些示例内容。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">is_active</span><span class="token punctuation">)</span><span class="token punctuation">:</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$field</span><span class="token operator">-&gt;</span><span class="token property">label</span> <span class="token delimiter important">?&gt;</span></span> is active<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">endif</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><h2 id="使用视图模板"><a href="#使用视图模板" class="header-anchor">#</a> 使用视图模板</h2><p>您可以将视图模板代码作为 <code>path</code> 传递，以访问插件内部的视图服务模板。以下代码将在路径 <strong>plugins/acme/blog/views/formfields/content.php</strong> 中找到。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">content</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> partial
    <span class="token key atrule">path</span><span class="token punctuation">:</span> acme.blog<span class="token punctuation">:</span><span class="token punctuation">:</span>formfields.content
</code></pre></div><p>您也可以将部件放在 app 目录中，例如 <strong>app/views/formfields/content.php</strong>。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">content</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> partial
    <span class="token key atrule">path</span><span class="token punctuation">:</span> app<span class="token punctuation">:</span><span class="token punctuation">:</span>formfields.content
</code></pre></div><div class="custom-block tip"><p>路径必须包含 <code>::</code> 字符才能激活视图服务。</p></div><h4 id="另请参阅"><a href="#另请参阅" class="header-anchor">#</a> 另请参阅</h4><div class="custom-block also"><ul><li><a href="./ui-hint.html">Hint 表单 UI</a></li><li><a href="./../../extend/system/views.html">渲染控制器视图</a></li><li><a href="./../../extend/services/response-view.html">响应与视图服务</a></li></ul></div>`,21))])}const _=p(r,[["render",d]]);export{y as __pageData,_ as default};
